CREATE TABLE [dbo].[ccMenus](	  [menu_id] SMALLINT NOT NULL	, [menu_descrip] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [parent] SMALLINT NULL	, [Nivel] CHAR(10) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('A')	, [ordengral] SMALLINT NOT NULL DEFAULT((1))	, [type] TINYINT NOT NULL DEFAULT((1))	, [HelpSWF] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('Error')	, [release] VARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, CONSTRAINT [PK_ccMenus] PRIMARY KEY ([menu_id] ASC, [type] ASC))CREATE NONCLUSTERED INDEX [IX_ccMenus] ON [dbo].[ccMenus] ([menu_id] ASC)